/*
 * A191327  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then [5x/2] and [7x/2] are in a, where [ ]=floor.
 * https://oeis.org/A191327
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1; if x∈a then ⌊5x/2⌋ and ⌊7x/2⌋ are also in a
 * Range:     u8 n <= 17, u16 n <= 316, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   heap_swap
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Implementation: generate the sequence on demand with a min‑heap of
    candidates, deduplicating by remembering the last value inserted.
    The code works for both 64‑bit and larger builds; the 64‑bit case
    avoids overflow by computing via unsigned __int128. */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/heap_swap.h"

/* ---------- comparison and swap for seq_t ---------- */
static inline int cmp_seq(const seq_t *a, const seq_t *b)
{
    return (*a < *b) ? -1 : (*a > *b ? 1 : 0);
}

/* ---------- min‑heap of seq_t values ---------- */
static seq_t *heap     = NULL;
static size_t heap_sz  = 0;
static size_t heap_cap = 0;

static void heap_push(seq_t v)
{
    if (heap_sz == heap_cap) {
        size_t new_cap = (heap_cap == 0) ? 16 : heap_cap * 2;
        seq_t *tmp = (seq_t *)realloc(heap, new_cap * sizeof(seq_t));
        if (!tmp) exit(EXIT_FAILURE);
        heap     = tmp;
        heap_cap = new_cap;
    }
    heap[heap_sz++] = v;

    /* sift up */
    size_t i = heap_sz - 1;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (cmp_seq(&heap[i], &heap[p]) >= 0) break;
        heap_swap(&heap[i], &heap[p]);
        i = p;
    }
}

static seq_t heap_pop(void)
{
    if (heap_sz == 0) exit(EXIT_FAILURE);
    seq_t minv = heap[0];
    heap_sz--;
    if (heap_sz > 0) {
        heap[0] = heap[heap_sz];
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            size_t r = l + 1;
            size_t smallest = i;
            if (l < heap_sz && cmp_seq(&heap[l], &heap[smallest]) < 0)
                smallest = l;
            if (r < heap_sz && cmp_seq(&heap[r], &heap[smallest]) < 0)
                smallest = r;
            if (smallest == i) break;
            heap_swap(&heap[i], &heap[smallest]);
            i = smallest;
        }
    }
    return minv;
}

/* ---------- storage for the sequence ---------- */
static seq_t *seq     = NULL;
static size_t seq_cnt = 0;
static size_t seq_cap = 0;
static seq_t last_val;
static int    last_set = 0;

static void ensure_seq_capacity(size_t n)
{
    if (seq_cap >= n) return;
    size_t new_cap = (seq_cap == 0) ? 16 : seq_cap;
    while (new_cap < n) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    seq    = tmp;
    seq_cap = new_cap;
}

/* Generate the sequence up to index n (1‑based). */
static void generate_up_to(idx_t n)
{
    if (seq_cnt >= (size_t)n) return;      /* already done */

    if (seq_cnt == 0) {
        heap_push((seq_t)1);               /* seed */
        ensure_seq_capacity((size_t)n);
    } else
        ensure_seq_capacity((size_t)n);

    while (seq_cnt < (size_t)n) {
        seq_t cur = heap_pop();

        if (last_set && cur == last_val) {
            /* duplicate – skip adding and do NOT generate children again */
            continue;
        }

        /* record new value */
        seq[seq_cnt++] = cur;
        last_val = cur;
        last_set = 1;

        /* generate and push children */
        if (sizeof(seq_t) <= sizeof(uint64_t)) {
            /* 64‑bit case – avoid overflow */
            unsigned __int128 prod5 = (unsigned __int128)cur * 5;
            if (prod5 <= (unsigned __int128)UINT64_MAX) {
                seq_t c1 = (seq_t)(prod5 / 2);
                heap_push(c1);
            }
            unsigned __int128 prod7 = (unsigned __int128)cur * 7;
            if (prod7 <= (unsigned __int128)UINT64_MAX) {
                seq_t c2 = (seq_t)(prod7 / 2);
                heap_push(c2);
            }
        } else {
            /* larger or arbitrary‑precision build – safe arithmetic */
            seq_t c1 = ((seq_t)5 * cur) / 2;
            seq_t c2 = ((seq_t)7 * cur) / 2;
            heap_push(c1);
            heap_push(c2);
        }
    }
}

/* ------------- public entry point ------------- */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;      /* undefined for n=0 */
    generate_up_to(n);
    return seq[n - 1];
}
